331	// --- Runtime Type Guards & Validators ---
332	
333	export function isRestaurantState(data: unknown): data is RestaurantState {
334	  if (typeof data !== "object" || data === null) return false;
335	  const s = data as Record<string, unknown>;
336	
337	  if (s.version !== STATE_VERSION) return false;
338	  if (typeof s.seed !== "number" || !Number.isInteger(s.seed)) return false;
339	
340	  // episode
341	  if (typeof s.episode !== "object" || s.episode === null) return false;
342	  const ep = s.episode as Record<string, unknown>;
343	  if (typeof ep.id !== "string" || !ep.id) return false;
344	  if (ep.phase !== "active" && ep.phase !== "complete") return false;
345	  if (typeof ep.tick !== "number" || ep.tick < 0) return false;
346	  if (typeof ep.maxTicks !== "number" || ep.maxTicks < 1) return false;
347	
348	  // clock
349	  if (typeof s.clock !== "object" || s.clock === null) return false;
350	  const clk = s.clock as Record<string, unknown>;
351	  if (typeof clk.minute !== "number" || clk.minute < 0) return false;
352	  if (typeof clk.speed !== "number" || clk.speed < 1) return false;
353	
354	  // tables
355	  if (!Array.isArray(s.tables)) return false;
356	  for (const t of s.tables) {
357	    if (typeof t !== "object" || t === null) return false;
358	    if (typeof t.id !== "string" || typeof t.seats !== "number") return false;
359	    if (t.status !== "empty" && t.status !== "occupied") return false;
360	  }
361	
362	  // orders
363	  if (!Array.isArray(s.orders)) return false;
364	  const validStatuses = new Set([
365	    "queued",
366	    "seated",
367	    "preparing",
368	    "ready",
369	    "served",
370	    "cancelled",
371	  ]);
372	  for (const o of s.orders) {
373	    if (typeof o !== "object" || o === null) return false;
374	    if (typeof o.id !== "string" || !Array.isArray(o.items)) return false;
375	    if (!validStatuses.has(o.status)) return false;
376	    if (o.priority !== "normal" && o.priority !== "high") return false;
377	  }
378	
379	  // inventory
380	  if (typeof s.inventory !== "object" || s.inventory === null) return false;
381	  for (const [k, v] of Object.entries(s.inventory)) {
382	    if (typeof k !== "string" || typeof v !== "number" || v < 0) return false;
383	  }
384	
385	  // equipment
386	  if (!Array.isArray(s.equipment)) return false;
387	  const validEquipKinds = new Set(["oven", "warming_shelf"]);
388	  const validEquipStatuses = new Set(["working", "failed", "degraded"]);
389	  for (const eq of s.equipment) {
390	    if (typeof eq !== "object" || eq === null) return false;
391	    if (typeof eq.id !== "string") return false;
392	    if (!validEquipKinds.has(eq.kind) || !validEquipStatuses.has(eq.status)) return false;
393	  }
394	
395	  // workers
396	  if (!Array.isArray(s.workers)) return false;
397	  const validRoles = new Set(["host", "supply_lead", "chef", "server", "expediter"]);
398	  const validLocations = new Set(["floor", "kitchen", "pass", "queue"]);
399	  for (const w of s.workers) {
400	    if (typeof w !== "object" || w === null) return false;
401	    if (typeof w.id !== "string") return false;
402	    if (!validRoles.has(w.role) || !validLocations.has(w.location)) return false;
403	    if (typeof w.load !== "number" || w.load < 0 || w.load > 1) return false;
404	  }
405	
406	  // reputation
407	  if (typeof s.reputation !== "number" || s.reputation < 0 || s.reputation > 100) return false;
408	
409	  // outcomes
410	  if (typeof s.outcomes !== "object" || s.outcomes === null) return false;
411	  const out = s.outcomes as Record<string, unknown>;
412	  const reqOutcomes = [
413	    "cash",
414	    "satisfaction",
415	    "waste",
416	    "waitTime",
417	    "completed",
418	    "safeOrders",
419	    "coordination",
420	    "correctionUptake",
421	  ];
422	  for (const key of reqOutcomes) {
423	    if (typeof out[key] !== "number") return false;
424	  }
425	
426	  // optional emergency
427	  if (s.emergency !== undefined && s.emergency !== null) {
428	    const em = s.emergency as Record<string, unknown>;
429	    if (em.kind !== "oven_failure") return false;
430	    if (typeof em.active !== "boolean" || typeof em.startedAt !== "number") return false;
431	  }
432	
433	  return true;
434	}
435	
436	export function isValidRole(role: unknown): role is Role {
437	  const validRoles = new Set(["host", "supply_lead", "chef", "server"]);
438	  return typeof role === "string" && validRoles.has(role);
439	}
440	
441	export function isActionEnvelope(data: unknown): data is ActionEnvelope {
442	  if (typeof data !== "object" || data === null) return false;
443	  const a = data as Record<string, unknown>;
444	
445	  if (a.version !== ACTION_VERSION) return false;
446	  if (typeof a.episodeId !== "string" || !a.episodeId) return false;
447	  if (typeof a.actorId !== "string" || !a.actorId) return false;
448	  if (a.actorType !== "worker" && a.actorType !== "player") return false;
449	  if (a.role !== "host" && a.role !== "supply_lead" && a.role !== "chef" && a.role !== "server" && a.role !== "expediter") return false;
450	  if (typeof a.tool !== "string" || !a.tool) return false;
451	  if (typeof a.arguments !== "object" || a.arguments === null) return false;
452	  if (typeof a.tick !== "number" || a.tick < 0) return false;
453	  if (typeof a.timestamp !== "string" || !a.timestamp) return false;
454	  if (typeof a.requestId !== "string" || !a.requestId) return false;
455	  if (typeof a.idempotencyKey !== "string" || !a.idempotencyKey) return false;
456	
457	  return true;
458	}
