1429	          );
1430	        }
1431	      }
1432	    }
1433	
1434	    // 2. Order Preparation Progress
1435	    for (const [orderId, remaining] of Array.from(this.prepRemaining.entries())) {
1436	      const nextRemaining = remaining - 1;
1437	      if (nextRemaining <= 0) {
1438	        this.prepRemaining.delete(orderId);
1439	        const order = this.currentState.orders.find((o) => o.id === orderId);
1440	        if (order && order.status === "preparing") {
1441	          order.status = "ready";
1442	        }
1443	      } else {
1444	        this.prepRemaining.set(orderId, nextRemaining);
1445	      }
1446	    }
1447	
1448	    // 3. The door: parties arrive, wait, get seated, or give up and leave.
1449	    this.runDoor(nextTick);
1450	
1451	    // 4. Worker autonomous baseline behaviors (simple progression for simulation)
1452	    this.progressWorkers();
1453	
1454	    // 4. A repair started by the player finishes on its own.
1455	    if (this.ovenRepairTicks > 0) {
1456	      this.ovenRepairTicks -= 1;
1457	      if (this.ovenRepairTicks === 0) {
1458	        const oven = this.currentState.equipment.find((e) => e.kind === "oven");
1459	        if (oven && oven.status === "degraded") oven.status = "working";
1460	      }
1461	    }
1462	
1463	    // 5. Reputation decay during emergencies, unless the host is holding the door.
1464	    if (this.currentState.emergency?.active && !this.currentState.seatingHeld) {
