1492	        kind: "outcome",
1493	        timestamp: this.timestampForTick(nextTick),
1494	        stateHash: outcomeHash,
1495	        actorId: "system",
1496	        text: `Shift outcome: $${this.currentState.outcomes.cash.toFixed(0)} takings, ${this.currentState.outcomes.completed} covers served, ${this.currentState.outcomes.safeOrders} safe plates.`,
1497	        outcome: {
1498	          cash: this.currentState.outcomes.cash,
1499	          satisfaction: this.currentState.outcomes.satisfaction,
1500	          waste: this.currentState.outcomes.waste,
1501	          waitTime: this.currentState.outcomes.waitTime,
1502	          completed: this.currentState.outcomes.completed,
1503	          safeOrders: this.currentState.outcomes.safeOrders,
1504	          coordination: this.currentState.outcomes.coordination,
1505	          correctionUptake: this.currentState.outcomes.correctionUptake,
1506	        },
