362	  constructor(seed = 218220, variationId?: string) {
363	    this.preset = (variationId && SHIFT_PRESETS[variationId]) || DEFAULT_SHIFT;
364	    this.roundContract = roundContractFor(this.preset.id);
365	    this.initialSeed = seed;
366	    this.rng = new Rng(seed);
367	    this.currentState = this.createInitialState(seed);
368	    this.initialStateSnapshot = this.currentState;
369	    this.reset(seed);
