372	  private createInitialState(seed: number): RestaurantState {
373	    const base = JSON.parse(JSON.stringify(fixture)) as RestaurantState;
374	    base.seed = seed;
375	    base.version = STATE_VERSION;
376	    base.episode.phase = "active";
377	    base.episode.tick = 0;
378	    base.episode.maxTicks = this.preset.maxTicks;
379	    base.clock.minute = 0;
380	    base.reputation = 50;
381	    // The fixture opens with a two-order pantry, which starves a full shift
382	    // of arriving parties within a few ticks.
383	    for (const [item, count] of Object.entries(OPENING_STOCK)) {
384	      base.inventory[item] = Math.max(base.inventory[item] ?? 0, count);
385	    }
386	    if (this.preset.id !== "dinner-rush") {
387	      base.episode.id = `${this.preset.id}-${seed}`;
388	    }
389	    if (this.preset.id === TUTORIAL_SHIFT_ID) {
390	      for (const order of base.orders) {
391	        delete order.allergy;
392	        order.priority = "normal";
393	      }
394	    }
395	    return base;
396	  }
