479	  private clockLabel(): string {
480	    // Service opens at 17:30; one tick is one minute of dinner service.
481	    const total = 17 * 60 + 30 + this.currentState.clock.minute;
482	    return `${String(Math.floor(total / 60) % 24).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
483	  }
