1382	    // The clock moves first so everything logged this tick is stamped with
1383	    // the time it actually happened.
1384	    this.currentState.episode.tick = nextTick;
1385	    this.currentState.clock.minute += this.currentState.clock.speed;
1386	
1387	    // 1. Scheduled Incidents
1388	    for (const incident of this.preset.incidents) {
1389	      if (incident.tick === nextTick) {
