1394	            kind: "oven_failure",
1395	            active: true,
1396	            startedAt: nextTick,
1397	          };
1398	          const incidentEventId = `evt-dec-allergy-${this.currentState.seed}`;
1399	          const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
1400	          const incidentHash = computeStateHash({ episodeId, incident: "oven_failure_and_allergy", tick: nextTick });
1401	          this.recordEvent({
1402	            tick: nextTick,
1403	            kind: "observation",
1404	            timestamp: this.timestampForTick(nextTick),
1405	            stateHash: incidentHash,
1406	            actorId: "system",
1407	            requestId: incidentEventId,
1408	            subject: {
1409	              kind: "equipment",
1410	              id: incident.targetId,
1411	            },
1412	            text: "Oven-1 failure occurred; peanut allergy constraint on Table 2 ticket requires verification.",
1413	            observation: {
1414	              emergency: { kind: "oven_failure", active: true },
1415	              orderId: "order-2",
1416	              allergy: "peanut",
1417	            },
1418	          });
1419	        } else if (incident.kind === "warming_shelf_overheat") {
