1	/**
2	 * Restaurant Arena Structured Trace Capture & Exporter (restaurant-arena-trace/v3).
3	 * Strictly aligns with contracts/restaurant-arena-trace-v3.schema.json.
4	 */
5	
6	import { SHIFT_PRESETS } from "./arena-view.js";
7	import type { ArenaInputRecord, RestaurantGame } from "./restaurant-game.js";
8	import { roundForTick } from "./rounds.js";
9	import {
10	  isRestaurantState,
11	  isActionEnvelope,
12	  type Outcomes,
13	  type Priority,
14	  type RestaurantState,
15	  type Role,
16	} from "./types.js";
17	
18	export const TRACE_V3_VERSION = "restaurant-arena-trace/v3" as const;
19	export const TRACE_V3_CONTRACT_VERSION = "restaurant-arena/v1" as const;
20	
21	/**
22	 * The arena build a trace was recorded against. Kept in step with the package
23	 * version by hand: the overlay bundles this module for the browser, where
24	 * reading package.json at runtime is not available.
25	 */
26	export const ARENA_ENV_VERSION = "0.3.4" as const;
27	
28	export type TraceEventKind =
29	  | "observation"
30	  | "action"
31	  | "player_correction"
32	  | "message"
33	  | "outcome"
34	  | "inspection"
35	  | "hold"
36	  | "hold_cleared"
37	  | "verification_request"
38	  | "verification_response"
39	  | "escalation"
40	  | "handoff"
41	  | "supply_order"
42	  | "supply_delivered"
43	  | "stockout";
44	
45	export type TraceV3Role = Role | "expediter";
46	
47	export interface TraceV3Model {
48	  provider: string;
49	  name: string;
50	  version?: string;
51	}
52	
53	export interface TraceV3Subject {
54	  kind: "order" | "ingredient" | "equipment" | "handoff";
55	  id: string;
56	}
57	
58	/**
59	 * The three keys a grader sorts on. Everything a tool returns beyond them
60	 * (`status: "verified"`, counts, ids) rides alongside untouched.
61	 */
62	export interface TraceV3ToolResult extends Record<string, unknown> {
63	  /** False on every rejected or failed call. Filter on this to select failures. */
64	  ok?: boolean;
65	  /** Model or tool round trip. Absent when no call stood behind the event. */
66	  latencyMs?: number;
67	  /** Time spent waiting for a shared account's request budget before the provider call started. */
68	  queueMs?: number;
69	  /** The provider call itself, excluding queueMs. Absent when the transport cannot separate the two. */
70	  providerMs?: number;
71	  /** Elapsed time since this decision round started, through this worker's own completion. */
72	  roundMs?: number;
73	  /** Absent fields below mean the provider did not report that count, not that it was zero. */
74	  inputTokens?: number;
75	  outputTokens?: number;
76	  cachedInputTokens?: number;
77	  finishReason?: string;
78	  error?: { code: string; message: string; retryable?: boolean } | null;
79	}
80	
81	export interface TraceV3Deletion {
82	  requestId: string | null;
83	  status: "retained" | "requested" | "deleted";
84	}
85	
86	export interface TraceV3Event {
87	  tick: number;
88	  /**
89	   * The decision round this event happened in (#262). Round *r* advances
90	   * ticks 2r-1 and 2r, so a reviewer can line a manager action up against the
91	   * worker turns it shaped without counting ticks by hand.
92	   */
93	  round?: number;
94	  kind: TraceEventKind;
95	  timestamp: string;
96	  stateHash: string;
97	  actorId?: string;
98	  role?: TraceV3Role;
99	  targetRole?: TraceV3Role;
100	  checkpointId?: string;
101	  model?: TraceV3Model;
102	  requestId?: string;
103	  idempotencyKey?: string;
104	  text?: string | null;
105	  observation?: Record<string, unknown> | null;
106	  action?: Record<string, unknown> | null;
107	  toolResult?: TraceV3ToolResult | null;
108	  outcome?: Record<string, unknown> | null;
109	  correctionRationale?: string | null;
110	  correctionCategory?: "safety" | "priority" | "quality" | "pace" | null;
111	  changedDecisionEventId?: string | null;
112	  probeEventId?: string | null;
113	  subject?: TraceV3Subject;
114	  payload?: Record<string, unknown> | null;
115	}
116	
117	export interface RestaurantArenaTraceV3 {
118	  version: typeof TRACE_V3_VERSION;
119	  episodeId: string;
120	  /**
121	   * The one run this trace came from.
122	   *
123	   * `episodeId` names the *scenario* -- `dinner-rush-218220` is the same
124	   * dinner rush every time it is played, and the benchmark fixture leans on
125	   * that. So it cannot identify a session: two people playing the same seed
126	   * export the same `episodeId`, which makes two sessions indistinguishable
127	   * on receipt and a re-export indistinguishable from a new one (#281).
128	   *
129	   * Optional so every v3 export written before this field stays valid. A
130	   * trace without one is a trace whose session cannot be matched, not a
131	   * malformed trace.
132	   */
133	  sessionId?: string;
134	  seed: number;
135	  envVersion: string;
136	  contractVersion: typeof TRACE_V3_CONTRACT_VERSION;
137	  runKind: "live" | "synthetic" | "benchmark";
138	  /** The world at tick 0. Required: without it a trace cannot be replayed. */
139	  initialState: Record<string, unknown>;
140	  events: TraceV3Event[];
141	  deletion: TraceV3Deletion;
142	  replay: {
143	    variation: string;
144	    inputs: ArenaInputRecord[];
145	    finalStateHash: string;
146	    /** Optional so earlier v3 exports remain valid. */
147	    finalRestaurantStateHash?: string;
148	  };
149	  terminal: { status: "active" | "completed" | "abandoned"; tick: number; reason: string | null };
150	}
151	
152	export interface TraceCaptureOptions {
153	  episodeId?: string;
154	  /**
155	   * The run's own identifier, carried through to the export so a receipt can
156	   * be matched back to the session that produced it. Omitted by callers that
157	   * have no session to name -- a script building a fixture, for instance.
158	   */
159	  sessionId?: string;
160	  /**
161	   * Which kind of run this is. Required: defaulting it would file a benchmark
162	   * episode as live gameplay, and the three must stay distinguishable.
163	   */
164	  runKind: "live" | "synthetic" | "benchmark";
165	  envVersion?: string;
166	  startTime?: string;
167	  /** Recorded, never inferred: a caller that omits it gets `retained` with no request id. */
168	  deletion?: Partial<TraceV3Deletion>;
169	  /** Omit to capture the run's own journal; pass to replace it wholesale. */
170	  events?: TraceV3Event[];
171	  additionalEvents?: TraceV3Event[];
172	}
173	
174	/**
175	 * Pure, deterministic SHA-256 implementation (FIPS 180-4).
176	 * Runs synchronously in any JavaScript runtime (Node, Bun, browser) without external dependencies.
177	 */
178	export function sha256Bytes(bytes: Uint8Array): string {
