// ── Standing corrections ─────────────────────────────────────────────

/**
 * Every correction currently in force, in issue order. A correction issued
 * mid-shift keeps binding its roles on every later turn until it is lifted,
 * so this is what the floor is actually answering to right now — not a log of
 * what the manager once said.
 */
activeDirectives(): StandingDirective[] {
  return this.directives.filter(isDirectiveInForce).map((directive) => ({ ...directive }));
}

/**
 * The corrections binding one role, in issue order. Lifted corrections are
 * gone from this list: a role is bound by what still stands.
 */
directivesFor(role: Role | "expediter"): StandingDirective[] {
  const canonical = (role === "expediter" ? "supply_lead" : role) as Role;
  return this.directives
    .filter((directive) => directiveBinds(directive, canonical))
    .map((directive) => ({ ...directive }));
}

/**
 * Lift a correction. This is the only way one stops binding — a correction
 * that is merely old is still in force, which is the whole point of making
 * them standing. Returns false when the id names nothing still in force, so a
 * double lift is visible to the caller rather than silently accepted.
 */
liftDirective(directiveId: string): boolean {
  const index = this.directives.findIndex(
    (directive) => directive.id === directiveId && isDirectiveInForce(directive),
  );
  const directive = this.directives[index];
  if (!directive) return false;
  const tick = this.currentState.episode.tick;
  this.directives[index] = { ...directive, liftedAtTick: tick };
  this.recordEvent({
    tick,
    kind: "hold_cleared",
    timestamp: this.timestampForTick(tick),
    stateHash: computeStateHash({
      episodeId: this.currentState.episode.id,
      lifted: directive.id,
      tick,
    }),
    actorId: "player",
    correctionCategory: directive.category,
    correctionRationale: directive.note,
    text: `Correction lifted: ${directive.note}.`,
  });
  return true;
}

/**
 * Put a correction in force. Re-issuing one that already stands (same
 * category, roles and ticket) is idempotent: pressing the safety control
 * twice is one instruction, not two things for the chef to answer to.
 */
private issueDirective(input: {
  category: DirectiveCategory;
  roles: readonly Role[];
  note: string;
  orderId?: string;
}): StandingDirective {
  const existing = this.directives.find(
    (directive) =>
      isDirectiveInForce(directive) &&
      directive.category === input.category &&
      directive.orderId === input.orderId &&
      directive.roles.length === input.roles.length &&
      directive.roles.every((role) => input.roles.includes(role)),
  );
  if (existing) return existing;

  this.directiveSequence += 1;
  const directive: StandingDirective = {
    id: `directive-${this.directiveSequence}`,
    category: input.category,
    roles: [...input.roles],
    note: input.note,
    issuedAtTick: this.currentState.episode.tick,
    sequence: this.directiveSequence,
    ...(input.orderId ? { orderId: input.orderId } : {}),
  };
  this.directives.push(directive);
  return directive;
}

/** Lift every correction in force in a category — how a hold is released. */
private liftDirectivesInCategory(category: DirectiveCategory): void {
  for (const directive of this.activeDirectives()) {
    if (directive.category === category) this.liftDirective(directive.id);
  }
}

/**
 * Hold the door as a standing correction, not just a flag. `seatingHeld`
 * stops the house script seating for the player; the correction is what binds
 * a model-driven host or server at the action boundary.
 */
private holdTheDoor(note: string): void {
  this.currentState.seatingHeld = true;
  this.issueDirective({ category: "pace", roles: ["host", "server"], note });
}

private reopenTheDoor(): void {
  this.currentState.seatingHeld = false;
  this.liftDirectivesInCategory("pace");
}

/**
 * Credit a worker for moving a correction along. `correctionUptake` is for
 * carrying one out; `coordination` is for work that advances one without
 * being the hands that execute it — see CORRECTIONS_AND_PROBE_CONTRACT.md §1.
 */
private creditDirective(directive: StandingDirective, role: Role, kind: DirectiveUptakeKind): void {
  const key = `${directive.id}:${role}:${kind}`;
  if (this.directiveCredits.has(key)) return;
  this.directiveCredits.add(key);
  const out = this.currentState.outcomes;
  if (kind === "carried_out" || kind === "coordinated") {
    out.correctionUptake = Math.min(1, out.correctionUptake + UPTAKE_STEP);
  }
  if (kind === "coordinated") {
    out.coordination = Math.min(1, out.coordination + COORDINATION_STEP);
  }
  if (kind === "relayed") {
    out.coordination = Math.min(1, out.coordination + RELAY_COORDINATION_STEP);
  }
}

/**
 * How the warming-shelf probe read the shift.
 *
 * The window opens the moment the shelf starts running warm and nothing
 * before that tick is evidence about it. `outcome` turns on whether the
 * trigger has fired and whether a false positive has landed since — never on
 * how many responses came in, so it reads `scope_held` from the instant the
 * trigger fires, with an empty `decisions` list, and only moves to
 * `over_generalized` when a worker actually over-generalises.
 */
probeReport(): ProbeReport {
  return buildProbeReport(this.eventJournal, this.shelfProbeTick);
}

