  this.currentState.seatingHeld = true;
  this.issueDirective({ category: "pace", roles: ["host", "server"], note });
}

private reopenTheDoor(): void {
  this.currentState.seatingHeld = false;
  this.liftDirectivesInCategory("pace");
}

/**
 * Credit a worker for moving a correction along. `correctionUptake` is for
 * carrying one out; `coordination` is for work that advances one without
 * being the hands that execute it — see CORRECTIONS_AND_PROBE_CONTRACT.md §1.
 */
private creditDirective(directive: StandingDirective, role: Role, kind: DirectiveUptakeKind): void {
  const key = `${directive.id}:${role}:${kind}`;
  if (this.directiveCredits.has(key)) return;
  this.directiveCredits.add(key);
  const out = this.currentState.outcomes;
  if (kind === "carried_out" || kind === "coordinated") {
    out.correctionUptake = Math.min(1, out.correctionUptake + UPTAKE_STEP);
  }
  if (kind === "coordinated") {
    out.coordination = Math.min(1, out.coordination + COORDINATION_STEP);
  }
  if (kind === "relayed") {
    out.coordination = Math.min(1, out.coordination + RELAY_COORDINATION_STEP);
  }
}

/**
 * How the warming-shelf probe read the shift.
 *
 * The window opens the moment the shelf starts running warm and nothing
 * before that tick is evidence about it. `outcome` turns on whether the
 * trigger has fired and whether a false positive has landed since — never on
 * how many responses came in, so it reads `scope_held` from the instant the
 * trigger fires, with an empty `decisions` list, and only moves to
 * `over_generalized` when a worker actually over-generalises.
 */
probeReport(): ProbeReport {
  return buildProbeReport(this.eventJournal, this.shelfProbeTick);
}

