/** The live allergy ticket a safety correction scopes itself to, if there is one. */
private liveAllergyOrderId(): string | undefined {
  return this.currentState.orders.find((o) => o.allergy && ACTIVE_ORDER_STATUSES.has(o.status))?.id;
}

/**
 * The safety correction, scoped to the allergy ticket that prompted it. Scope
 * matters: an unverified swap on *that* ticket is refused, while the rest of
 * the board keeps moving — widening it to the whole service is exactly what
 * the shelf probe grades against.
 */
private issueSafetyDirective(note: string): StandingDirective {
  const orderId = this.liveAllergyOrderId();
  return this.issueDirective({
    category: "safety",
    roles: ["chef"],
    note,
    ...(orderId ? { orderId } : {}),
  });
}

