import { RestaurantGame } from "/app/src/games/restaurant-arena/restaurant-game.js";
import { ACTION_VERSION, type ActionEnvelope, type Role, type Tool } from "/app/src/games/restaurant-arena/types.js";
let n = 0;
function env(g: RestaurantGame, role: Role, tool: Tool, args: Record<string, unknown>): ActionEnvelope {
  const s = g.state();
  const rid = `req-${++n}`;
  return { version: ACTION_VERSION, episodeId: s.episode.id, actorId: `worker-${role}`, actorType: "worker", role, tool, arguments: args, tick: s.episode.tick, timestamp: new Date().toISOString(), requestId: rid, idempotencyKey: `${s.episode.id}:${rid}` };
}
const g = new RestaurantGame(218220);
g.setExternalControllers(["host", "chef", "server", "supply_lead"]);
g.step("sim_start");
const host = g.observe("host");
console.log("host obs keys:", Object.keys(host));
console.log("queue:", JSON.stringify((host as any).queue ?? (host as any).waiting));
console.log("tables:", g.state().tables.map(t=>`${t.id}:${t.status}`).join(" "));
g.step("verify_substitution");
let r = g.stepEnvelope(env(g, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }));
console.log("unverified swap:", r.accepted, r.error?.code, r.error?.message);
r = g.stepEnvelope(env(g, "chef", "prepare", { orderId: "order-1", substitution: "house sauce" }));
console.log("swap on other ticket:", r.accepted, r.error?.code);
console.log("uptake before verify:", g.state().outcomes.correctionUptake);
r = g.stepEnvelope(env(g, "chef", "prepare", { orderId: "order-2", substitution: "house sauce", verified: true }));
console.log("verified swap:", r.accepted, "uptake:", g.state().outcomes.correctionUptake);
// hold the door
g.step("hold_seating");
console.log("held:", g.state().seatingHeld, "pace:", JSON.stringify(g.directivesFor("host")));
const party = (host as any).queue?.[0];
console.log("party:", JSON.stringify(party));
