g.step("hold_seating");
console.log("after toggle held:", g.state().seatingHeld, "pace:", g.directivesFor("host").length);
r = g.stepEnvelope(env(g, "host", "seat", { tableId: "table-4", partyId: party?.id ?? "party-1" }));
console.log("seat after release:", r.accepted, r.error?.code, r.error?.message);
EOF
