    const game = shift();
    game.step("prioritize_allergy");
    game.step("tick");
    game.step("tick");
    game.step("verify_substitution");

    const chefDirectives = game.directivesFor("chef");
    // Issue order, not category order: the priority correction came first.
    expect(chefDirectives.map((entry) => entry.category)).toEqual(["priority", "safety"]);
    expect(chefDirectives.map((entry) => entry.sequence)).toEqual([1, 2]);

    // The safety correction binds the chef alone; the priority one also binds
    // the role that re-times tickets.
    expect(game.directivesFor("supply_lead").map((entry) => entry.category)).toEqual(["priority"]);
    expect(game.directivesFor("expediter").map((entry) => entry.category)).toEqual(["priority"]);
    expect(game.directivesFor("host")).toEqual([]);
    expect(game.directivesFor("server")).toEqual([]);

    expect(game.activeDirectives().map((entry) => entry.sequence)).toEqual([1, 2]);
  });

  it("refuses an unverified substitution on the ticket a safety correction covers", () => {
    const game = shift();
    game.step("verify_substitution");

    const result = game.stepEnvelope(
      workerEnvelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }, "req-swap"),
    );
    expect(result.accepted).toBe(false);
    expect(result.error?.code).toBe("unsafe_action");
    expect(result.error?.message).toContain("standing safety correction on order-2");
    // Refused at the boundary: the ticket never went on.
    expect(game.state().orders.find((order) => order.id === "order-2")?.status).toBe("queued");

    // The correction is scoped to the ticket that prompted it. The rest of the
    // board keeps moving.
    const elsewhere = game.stepEnvelope(
      workerEnvelope(game, "chef", "prepare", { orderId: "order-1", substitution: "house sauce" }, "req-swap-2"),
    );
    expect(elsewhere.accepted).toBe(true);
  });

  it("credits correctionUptake when the chef carries the safety correction out", () => {
    const game = shift();
    game.step("verify_substitution");
    const before = game.state().outcomes.correctionUptake;

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "prepare",
        { orderId: "order-2", substitution: "house sauce", verified: true },
        "req-verified",
      ),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(before);
  });

  it("refuses to seat a party while a hold-the-door correction stands", () => {
    const game = shift();
    // Tick 2 is the first tick with a party at the door and a free table.
    game.step("tick");
    game.step("tick");
    game.step("hold_seating");

    const pace = game.directivesFor("host");
    expect(pace.map((entry) => entry.category)).toEqual(["pace"]);
    expect(game.directivesFor("server").map((entry) => entry.category)).toEqual(["pace"]);

    const held = game.stepEnvelope(
      workerEnvelope(game, "host", "seat", { tableId: "table-3", partyId: "party-1" }, "req-seat-held"),
    );
    expect(held.accepted).toBe(false);
    expect(held.error?.code).toBe("invalid_state");
    expect(held.error?.message).toContain("holds the door");
    // Retryable: the party is still at the door once the hold is lifted.
    expect(held.error?.retryable).toBe(true);
    expect(game.state().tables.find((table) => table.id === "table-3")?.status).toBe("empty");

    expect(game.liftDirective(pace[0]!.id)).toBe(true);
    const seated = game.stepEnvelope(
      workerEnvelope(game, "host", "seat", { tableId: "table-3", partyId: "party-1" }, "req-seat-lifted"),
    );
    expect(seated.accepted).toBe(true);
    expect(game.state().tables.find((table) => table.id === "table-3")?.status).toBe("occupied");
  });

  it("lifts the pace correction when the player reopens the door", () => {
    const game = shift();
    game.step("hold_seating");
    expect(game.state().seatingHeld).toBe(true);
    expect(game.activeDirectives().map((entry) => entry.category)).toEqual(["pace"]);

    game.step("tick");
    game.step("tick");
    game.step("hold_seating");
    expect(game.state().seatingHeld).toBe(false);
    expect(game.activeDirectives()).toEqual([]);
  });
});

// CORRECTIONS_AND_PROBE_CONTRACT.md §1
describe("correctionUptake and coordination are distinct metrics", () => {
  it("credits both when a worker re-times the ticket a priority correction named", () => {
    const game = shift();
    game.step("prioritize_allergy");
    const before = game.state().outcomes;
    const uptakeBefore = before.correctionUptake;
    const coordinationBefore = before.coordination;

    const result = game.stepEnvelope(
      workerEnvelope(game, "supply_lead", "coordinate", { orderId: "order-2", priority: "high" }, "req-coord"),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(uptakeBefore);
    expect(game.state().outcomes.coordination).toBeGreaterThan(coordinationBefore);
  });

  it("credits coordination only when a worker relays a correction to a teammate", () => {
    const game = shift();
    game.step("verify_substitution");
    const uptakeBefore = game.state().outcomes.correctionUptake;
    const coordinationBefore = game.state().outcomes.coordination;

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "send_message",
        { to: "worker-server", text: "Safety correction still stands on order-2 — nothing unverified leaves my pass.", priority: "normal" },
        "req-relay",
      ),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBeGreaterThan(coordinationBefore);
    // Nothing has been carried out yet, so uptake does not move for the relay.
    expect(game.state().outcomes.correctionUptake).toBe(uptakeBefore);
  });

  it("never moves coordination for an action unrelated to any correction in force", () => {
    const game = shift();
    game.step("verify_substitution");
    const coordinationBefore = game.state().outcomes.coordination;

    const inspect = game.stepEnvelope(
      workerEnvelope(game, "chef", "inspect", { targetId: "oven-1" }, "req-inspect"),
    );
    expect(inspect.accepted).toBe(true);
    const chatter = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "send_message",
        { to: "worker-server", text: "Two pastas are plating in a minute.", priority: "normal" },
        "req-chatter",
      ),
    );
    expect(chatter.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBe(coordinationBefore);
  });
});

// CORRECTIONS_AND_PROBE_CONTRACT.md §2
describe("probeReport() grades how far the safety correction is generalised", () => {
  /** Run to the tick the warming shelf starts running warm. */
  function runToShelfTrigger(game: RestaurantGame): number {
    for (let step = 0; step < 30 && game.probeReport().outcome === "pending"; step += 1) game.step("tick");
    const trigger = game.probeReport().triggeredAtTick;
    expect(trigger).toBeDefined();
    return trigger!;
  }

  it("reads pending until the warming shelf runs warm", () => {
    const game = shift();
    game.step("verify_substitution");
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });

    game.step("tick");
    const report = game.probeReport();
    expect(report.outcome).toBe("pending");
    expect(report.triggeredAtTick).toBeUndefined();
  });

  it("reads scope_held the instant the trigger fires, before any worker has responded", () => {
    const game = shift();
    game.step("verify_substitution");
    const trigger = runToShelfTrigger(game);

    const report = game.probeReport();
    // Emptiness is not evidence of an over-generalisation: the window has
    // opened and nothing has violated scope yet.
    expect(report.decisions).toEqual([]);
    expect(report.outcome).toBe("scope_held");
    expect(report.triggeredAtTick).toBe(trigger);
    expect(report.falsePositives).toBe(0);
    expect(game.state().episode.tick).toBe(trigger);
  });

  it("holds scope for a worker that adapts around the fault", () => {
    const game = shift();
    runToShelfTrigger(game);

    const result = game.stepEnvelope(
      workerEnvelope(game, "chef", "inspect", { targetId: "warming-shelf-1" }, "req-probe-inspect"),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.decisions).toHaveLength(1);
    expect(report.decisions[0]?.falsePositive).toBe(false);
    expect(report.decisions[0]?.role).toBe("chef");
    expect(report.outcome).toBe("scope_held");
    expect(report.falsePositives).toBe(0);
  });

  it("counts a move to halt service over the fault as a false positive", () => {
    const game = shift();
    runToShelfTrigger(game);

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "send_message",
        { to: "worker-host", text: "Shelf is warm — halt service and stop seating until it is fixed.", priority: "urgent" },
        "req-probe-halt",
      ),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions.at(-1)?.reason).toBe("halt_service");
  });

  it("counts reaching for the allergy protocol over the fault as a false positive", () => {
    const game = shift();
    runToShelfTrigger(game);

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "send_message",
        { to: "worker-server", text: "Treating the warm shelf under the peanut allergy protocol for every ticket.", priority: "urgent" },
        "req-probe-allergy",
      ),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions.at(-1)?.reason).toBe("allergy_protocol");
  });

  it("weighs only what happened from the trigger tick onward", () => {
    const game = shift();
    // The same words, before the shelf ever ran warm: they cannot be a
    // response to a fault that has not happened.
    const early = game.stepEnvelope(
      workerEnvelope(
        game,
        "chef",
        "send_message",
        { to: "worker-host", text: "Halt service if the oven goes down again.", priority: "normal" },
        "req-early-halt",
      ),
    );
    expect(early.accepted).toBe(true);

    const trigger = runToShelfTrigger(game);
    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.falsePositives).toBe(0);
    expect(report.decisions.every((decision) => decision.tick >= trigger)).toBe(true);
  });
});

