  const format = options.format ?? "markdown";
  const formattedObs = formatObservation(obs, format);
  const directives = options.directives ?? [];
  // Standing corrections come after the observation and before the ask: they
  // are the constraints the next action is chosen under, and they stay in the
  // prompt every turn until the manager lifts them.
  const standing = directives.length
    ? `\n## Standing Manager Corrections (in force until lifted)\n${directives
        .map((directive) => `- ${describeDirective(directive)}`)
        .join("\n")}\nThese bind this turn and every later turn. Keep each one to the scope it names — do not widen a correction to the whole service — and do not act against one; an action that breaks a correction is refused at the boundary.\n`
    : "";

  return `You are acting as the ${obs.role.toUpperCase()}. Here is your current situation observation for Tick ${obs.tick}:

${formattedObs}
${standing}
