describe("A worker's turn prompt re-states the corrections binding it", () => {
  it("lists the role's corrections every turn, and nothing for a role none bind", () => {
    const game = shift();
    game.step("verify_substitution");

    const chefPrompt = buildRoleTurnPrompt(game.observe("chef"), { directives: game.directivesFor("chef") });
    expect(chefPrompt).toContain("Standing Manager Corrections");
    expect(chefPrompt).toContain("[SAFETY] since tick 0 - verify before substituting on order-2");

    const hostPrompt = buildRoleTurnPrompt(game.observe("host"), { directives: game.directivesFor("host") });
    expect(hostPrompt).not.toContain("Standing Manager Corrections");

    // Still in the prompt several ticks later — that is what standing means.
    game.step("tick");
    game.step("tick");
    const laterPrompt = buildRoleTurnPrompt(game.observe("chef"), { directives: game.directivesFor("chef") });
    expect(laterPrompt).toContain("verify before substituting on order-2");
  });
});

